#import "PVXMediaResource.h"
static const NSUInteger PVXMediaMaxQueue=3;
static dispatch_queue_t PVXMRStateQueue; static NSMutableDictionary *PVXMRInflight; static NSCache *PVXMRCache; static NSMutableSet *PVXMRActive; static NSMutableArray *PVXMRPending; static dispatch_once_t PVXMROnce;
static void PVXMRSetup(void){dispatch_once(&PVXMROnce,^{PVXMRStateQueue=dispatch_queue_create("com.pyvideo.media-resource",DISPATCH_QUEUE_SERIAL);PVXMRInflight=[NSMutableDictionary dictionary];PVXMRCache=[NSCache new];PVXMRCache.countLimit=64;PVXMRActive=[NSMutableSet set];PVXMRPending=[NSMutableArray array];});}
static NSString *PVXMRKey(NSURLRequest *r,NSUInteger m,NSUInteger f){return [NSString stringWithFormat:@"%@|%@|%@|%lu|%lu",r.HTTPMethod?:@"GET",r.URL.absoluteString?:@"",r.allHTTPHeaderFields?:@{},(unsigned long)m,(unsigned long)f];}
static BOOL PVXMRDomain(NSHTTPCookie *c,NSString *h){NSString *d=c.domain.lowercaseString;BOOL sub=[d hasPrefix:@"."];if(sub)d=[d substringFromIndex:1];return [h isEqual:d]||(sub&&[h hasSuffix:[@"." stringByAppendingString:d]]);}
NSArray<NSHTTPCookie *> *PVXMediaCookiesForURL(NSArray<NSHTTPCookie *> *cs,NSURL *u){if(!u.host.length)return @[];NSString *p=u.path.length?u.path:@"/";NSMutableArray *a=[NSMutableArray array];for(NSHTTPCookie *c in cs){NSString *cp=c.path.length?c.path:@"/";BOOL po=[p isEqual:cp]||([p hasPrefix:cp]&&([cp hasSuffix:@"/"]||(p.length>cp.length&&[p characterAtIndex:cp.length]=='/')));BOOL secure=!c.secure||[u.scheme.lowercaseString isEqual:@"https"];BOOL live=!c.expiresDate||c.expiresDate.timeIntervalSinceNow>0;if(PVXMRDomain(c,u.host.lowercaseString)&&po&&secure&&live)[a addObject:c];}return a;}
static void PVXMRFinish(NSString *key,NSData *data,NSURL *file,NSHTTPURLResponse *resp,NSError *err){dispatch_async(PVXMRStateQueue,^{[PVXMRActive removeObject:key];if(!err&&data)[PVXMRCache setObject:data forKey:key];NSArray *blocks=[PVXMRInflight[key] copy];[PVXMRInflight removeObjectForKey:key];if(PVXMRPending.count){void(^next)(void)=[PVXMRPending.firstObject copy];[PVXMRPending removeObjectAtIndex:0];next();}dispatch_async(dispatch_get_main_queue(),^{for(PVXMediaResourceCompletion b in blocks)b(data,file,resp,err);});});}
@interface PVXMRDelegate:NSObject<NSURLSessionDataDelegate,NSURLSessionDownloadDelegate>@property(nonatomic,copy)NSString *key;@property(nonatomic)NSUInteger memory,fileLimit;@property(nonatomic,strong)NSMutableData *data;@property(nonatomic,strong)NSURL *file;@property(nonatomic,strong)NSFileHandle *handle;@property(nonatomic,weak)NSURLSession *session;@property(nonatomic,strong)NSHTTPURLResponse *response;@end
@implementation PVXMRDelegate
-(void)URLSession:(NSURLSession*)s dataTask:(NSURLSessionDataTask*)t didReceiveResponse:(NSURLResponse*)r completionHandler:(void (^)(NSURLSessionResponseDisposition))h{self.response=(id)r;h(NSURLSessionResponseAllow);}
-(void)URLSession:(NSURLSession*)s dataTask:(NSURLSessionDataTask*)t didReceiveData:(NSData*)d{if(!self.data)self.data=[NSMutableData data];if(self.data.length+d.length>self.memory){[t cancel];return;}[self.data appendData:d];}
-(void)URLSession:(NSURLSession*)s downloadTask:(NSURLSessionDownloadTask*)t didWriteData:(int64_t)b totalBytesWritten:(int64_t)n totalBytesExpectedToWrite:(int64_t)e{if(n>(int64_t)self.fileLimit||(e>0&&e>(int64_t)self.fileLimit)){[t cancel];}}
-(void)URLSession:(NSURLSession*)s downloadTask:(NSURLSessionDownloadTask*)t didFinishDownloadingToURL:(NSURL*)u{NSString *p=[NSTemporaryDirectory() stringByAppendingPathComponent:[NSString stringWithFormat:@"pvx-%@",NSUUID.UUID.UUIDString]];if([[NSFileManager defaultManager]copyItemAtPath:u.path toPath:p error:nil])self.file=[NSURL fileURLWithPath:p];}
-(void)URLSession:(NSURLSession*)s task:(NSURLSessionTask*)t willPerformHTTPRedirection:(NSHTTPURLResponse*)r newRequest:(NSURLRequest*)nr completionHandler:(void (^)(NSURLRequest*))h{NSMutableURLRequest *x=[nr mutableCopy];[x setValue:nil forHTTPHeaderField:@"Cookie"];h(x);}
-(void)URLSession:(NSURLSession*)s task:(NSURLSessionTask*)t didCompleteWithError:(NSError*)e{NSHTTPURLResponse *response=[t.response isKindOfClass:NSHTTPURLResponse.class]?(id)t.response:self.response;NSError *err=e;if(!err&&response.statusCode>=400)err=[NSError errorWithDomain:@"PVXMediaResource" code:response.statusCode userInfo:@{NSLocalizedDescriptionKey:[NSString stringWithFormat:@"HTTP %ld",(long)response.statusCode]}];PVXMRFinish(self.key,self.data,self.file,response,err);[s finishTasksAndInvalidate];}
@end

void PVXMediaResourceFetch(NSURLRequest *request,NSUInteger maxMemoryBytes,NSUInteger maxFileBytes,PVXMediaResourceCompletion completion){PVXMRSetup();if(!request.URL||!completion)return;NSString *key=PVXMRKey(request,maxMemoryBytes,maxFileBytes);dispatch_async(PVXMRStateQueue,^{NSData *cached=[PVXMRCache objectForKey:key];if(cached){dispatch_async(dispatch_get_main_queue(),^{completion(cached,nil,nil,nil);});return;}NSMutableArray *wait=PVXMRInflight[key];if(wait){[wait addObject:[completion copy]];return;}PVXMRInflight[key]=[NSMutableArray arrayWithObject:[completion copy]];void(^start)(void)=^{[PVXMRActive addObject:key];NSURLSessionConfiguration *cfg=[NSURLSessionConfiguration ephemeralSessionConfiguration];cfg.HTTPCookieStorage=nil;cfg.HTTPShouldSetCookies=NO;cfg.timeoutIntervalForRequest=20;cfg.timeoutIntervalForResource=30;PVXMRDelegate *d=[PVXMRDelegate new];d.key=key;d.memory=maxMemoryBytes?:65536;d.fileLimit=maxFileBytes;NSURLSession *s=[NSURLSession sessionWithConfiguration:cfg delegate:d delegateQueue:nil];d.session=s;BOOL file=maxFileBytes>0;NSURLSessionTask *task=file?[s downloadTaskWithRequest:request]:[s dataTaskWithRequest:request];[task resume];};if(PVXMRActive.count<PVXMediaMaxQueue)start();else{[PVXMRPending addObject:^{if(PVXMRInflight[key])start();}];dispatch_after(dispatch_time(DISPATCH_TIME_NOW,30*NSEC_PER_SEC),PVXMRStateQueue,^{if([PVXMRInflight[key] count]){NSError *e=[NSError errorWithDomain:@"PVXMediaResource" code:408 userInfo:@{NSLocalizedDescriptionKey:@"媒体请求排队超时"}];PVXMRFinish(key,nil,nil,nil,e);}});}});}
void PVXMediaResourceCancelAll(void){PVXMRSetup();dispatch_async(PVXMRStateQueue,^{[PVXMRInflight removeAllObjects];[PVXMRActive removeAllObjects];[PVXMRCache removeAllObjects];});}
